246	        OwnerPageDto ownerPageDto = new OwnerPageDto();
247	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
248	        ownerPageDto.setPage(ownerPage.getNumber());
249	        ownerPageDto.setSize(ownerPage.getSize());
250	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
251	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
252	        return ownerPageDto;
253	    }
