20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "bulkSignupWarning", ignore = true)
32	    @Mapping(target = "identityKey", ignore = true)
33	    @Mapping(target = "possibleDuplicate", ignore = true)
34	    @Mapping(target = "possibleDuplicateOf", ignore = true)
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's {@code contactPreference} from the owner's own fields:
39	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
40	     *
41	     * @param owner the owner being mapped
42	     * @return the derived contact preference
43	     */
44	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
45	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
46	    }
47	
48	    /**
49	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
50	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
51	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
52	     * rather than repeated at each use.
53	     *
54	     * @param owner the owner being mapped
55	     * @return {@code true} when the owner has a non-blank email
56	     */
57	    default boolean hasEmail(Owner owner) {
58	        return owner.getEmail() != null && !owner.getEmail().isBlank();
59	    }
60	
61	    /**
62	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
63	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
64	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
65	     * case the field is absent from the response. The age in whole years is the number of complete
66	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
67	     * registration date is somehow absent the current date is used as the reference.
68	     *
69	     * @param owner the owner being mapped
70	     * @return the derived age band, or {@code null} when no birth date is present
71	     */
72	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
73	        java.time.LocalDate birthDate = owner.getBirthDate();
74	        if (birthDate == null) {
75	            return null;
76	        }
77	        java.time.LocalDate reference = owner.getRegistrationDate() != null
78	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
79	        int age = java.time.Period.between(birthDate, reference).getYears();
80	        if (age < 18) {
81	            return OwnerDto.AgeBandEnum.MINOR;
82	        }
83	        if (age < 65) {
84	            return OwnerDto.AgeBandEnum.ADULT;
85	        }
86	        return OwnerDto.AgeBandEnum.SENIOR;
87	    }
88	
89	    /**
90	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
91	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
92	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
93	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
94	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
95	     * identity keeps the locality consistent with the code an owner is issued.
96	     *
97	     * @param owner the owner being mapped
98	     * @return the derived locality
99	     */
100	    default String locality(Owner owner) {
101	        String code = owner.getCustomerCode();
102	        if (code == null) {
103	            return Region.code(owner.getPostcode(), owner.getCity());
104	        }
105	        int dash = code.indexOf('-');
106	        return dash >= 0 ? code.substring(0, dash) : code;
107	    }
108	
109	    /**
110	     * Derives the owner's numeric {@code membershipLevel} from the owner's own fields. Starts at
111	     * {@code 1}, adds {@code 1} when an email is present, and adds {@code 1} when the owner's
112	     * {@code namesakeCount} is {@code 0}. These pre-tenure factors are capped at {@code 3}. Level
113	     * {@code 4} is reserved for tenure: it is granted only when the owner's tenure &mdash; the number
114	     * of whole days between its {@code registrationDate} and the current date &mdash; exceeds
115	     * {@code 365}. Because a newly created owner has zero tenure, a new owner never exceeds level
116	     * {@code 3}, even with an email and a {@code namesakeCount} of {@code 0}.
117	     *
118	     * @param owner the owner being mapped
119	     * @return the derived membership level, between {@code 1} and {@code 4}
120	     */
121	    default Integer membershipLevel(Owner owner) {
122	        int level = 1;
123	        if (hasEmail(owner)) {
124	            level++;
125	        }
126	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
127	        if (uniqueName) {
128	            level++;
129	        }
130	        level = Math.min(level, 3);
131	        if (tenureDays(owner) > 365) {
132	            level++;
133	        }
134	        return level;
135	    }
136	
137	    /**
138	     * Computes the owner's tenure in whole days: the number of complete days between the owner's
139	     * {@code registrationDate} and the current date. Returns {@code 0} when no registration date is
140	     * present, so an owner without a registration date has no tenure.
141	     *
142	     * @param owner the owner being mapped
143	     * @return the owner's tenure in whole days, or {@code 0} when no registration date is present
144	     */
145	    default long tenureDays(Owner owner) {
146	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
147	        if (registrationDate == null) {
148	            return 0;
149	        }
150	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
151	    }
152	
153	    /**
154	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
155	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
156	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
157	     * registration date is absent.
158	     *
159	     * @param owner the owner being mapped
160	     * @return the formatted membership number, or {@code null} when it cannot be derived
161	     */
162	    default String membershipNumber(Owner owner) {
163	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
164	            return null;
165	        }
166	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
167	    }
168	
169	    /**
170	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
171	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
172	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
173	     * the customer code is absent.
174	     *
175	     * @param owner the owner being mapped
176	     * @return the Luhn check digit, or {@code null} when no customer code is present
177	     */
178	    default Integer checkDigit(Owner owner) {
179	        String code = owner.getCustomerCode();
180	        if (code == null) {
181	            return null;
182	        }
183	        int sum = 0;
184	        boolean dbl = true;
185	        for (int i = code.length() - 1; i >= 0; i--) {
186	            char c = code.charAt(i);
187	            if (c < '0' || c > '9') {
188	                continue;
189	            }
190	            int d = c - '0';
191	            if (dbl) {
192	                d *= 2;
193	                if (d > 9) {
194	                    d -= 9;
195	                }
196	            }
197	            sum += d;
198	            dbl = !dbl;
199	        }
200	        return (10 - (sum % 10)) % 10;
201	    }
202	
203	    /**
204	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
205	     * code, a space, then the national-significant digits grouped in threes separated by spaces
206	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
207	     * field keeps the unformatted E.164 value. The split between the country code and the national
208	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
209	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
210	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
211	     * {@code null}, blank, or not in E.164 form.
212	     *
213	     * @param owner the owner being mapped
214	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
215	     */
216	    default String telephoneDisplay(Owner owner) {
217	        String telephone = owner.getTelephone();
218	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
219	            return telephone;
220	        }
221	        String digits = telephone.substring(1);
222	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
223	        String countryCode = digits.substring(0, codeLength);
224	        String national = digits.substring(codeLength);
225	        StringBuilder grouped = new StringBuilder();
226	        for (int i = 0; i < national.length(); i++) {
227	            if (i > 0 && i % 3 == 0) {
228	                grouped.append(' ');
229	            }
230	            grouped.append(national.charAt(i));
231	        }
232	        return "+" + countryCode + " " + grouped;
233	    }
234	
235	    Owner toOwner(OwnerDto ownerDto);
236	
237	    @Mapping(target = "id", ignore = true)
238	    @Mapping(target = "pets", ignore = true)
239	    Owner toOwner(OwnerFieldsDto ownerDto);
240	
241	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
242	
243	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
244	
245	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
246	        OwnerPageDto ownerPageDto = new OwnerPageDto();
247	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
248	        ownerPageDto.setPage(ownerPage.getNumber());
249	        ownerPageDto.setSize(ownerPage.getSize());
250	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
251	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
252	        return ownerPageDto;
253	    }
254	}
