73	    private Integer namesakeCount;
74	
75	    @Column(name = "possible_duplicate_of")
76	    private Integer possibleDuplicateOf;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
