169	    protected Set<Pet> getPetsInternal() {
170	        if (this.pets == null) {
171	            this.pets = new HashSet<>();
172	        }
173	        return this.pets;
174	    }
175	
176	    protected void setPetsInternal(Set<Pet> pets) {
177	        this.pets = pets;
178	    }
