232	
233	            .append("id", this.getId())
234	            .append("new", this.isNew())
235	            .append("lastName", this.getLastName())
236	            .append("firstName", this.getFirstName())
237	            .append("address", this.address)
238	            .append("city", this.city)
239	            .append("telephone", this.telephone)
240	            .toString();
241	    }
242	}
